// 清除文本里 callout 的视觉包装（callout 在开头或中间都行），保留正文内容与所有空行。
// 只匹配带 [!类型] 头的块，避免误伤普通引用(>)。
return text.replace(
  /(^[ \t]*>?[ \t]*\[![\w-]+\]-?[^\n]*\n)((?:^[ \t]*>[^\n]*\n?)*)/gm,
  (_, _h, body) => body.replace(/^[ \t]*>?[ \t]?/gm, '')
);

// 清除文本里普通引用(>) 的视觉包装，保留正文内容。
// 带 [!类型] 头的 callout 块由「清除Callout样式」先行处理，这里跳过其头部行，
// 仅剥离其余以 > 开头的引用行前缀。逐行处理，原样保留所有空行。
return text.split('\n').map(line => {
  if (/^[ \t]*>?[ \t]*\[![\w-]+\]/.test(line)) return line; // 跳过 callout 头部
  return line.replace(/^[ \t]*>[ \t]?/, '');
}).join('\n');

// 覆盖式：先清掉已有开始标记与选项标记，再在开头加开始标记、末尾加选项标记
const startMark = '【TBPX29待处理文本开始，请设置选项并后执行】';
const optMark = '【TBPX29本段文字用于让您选择你想要设置的Callout类型，请在最后输入想要的类型，1=note，2=note，3=abstract，4=info，5=todo，6=tip，7=success，8=question，9=warning，10=failure，11=danger，12=bug，13=example，14=quote，您需要的类型是=】';
let t = text
  .replace(/
?【TBPX29待处理文本开始[^
】]*】
?/g, '')
  .replace(/
?【TBPX29本段文字用于让您选择[^】]*您需要的类型是=[^
】]*】
?/g, '');
t = t.replace(/^
+/, '').replace(/
+$/, '');
return startMark + '
' + t + '
' + optMark;

function resolveType(opt) {
  const map = {
    '1':'note','2':'note','3':'abstract','4':'info','5':'todo','6':'tip',
    '7':'success','8':'question','9':'warning','10':'failure','11':'danger',
    '12':'bug','13':'example','14':'quote'
  };
  if (map[opt]) return map[opt];
  const known = ['note','abstract','info','todo','tip','success','question','warning','failure','danger','bug','example','quote'];
  return known.includes(opt) ? opt : null;
}
// 守卫：没有开始标记 → 未正确从标记处选择，原样返回、不执行
if (text.indexOf('【TBPX29待处理文本开始') === -1) return text;
// 全局收集选项标记，取第一个有效选项
const all = [...text.matchAll(/【TBPX29本段文字用于让您选择[^】]*您需要的类型是=([^\n】]*)】/g)];
let type = null;
for (const m of all) {
  const t = resolveType((m[1] || '').trim());
  if (t) { type = t; break; }
}
// 有开始标记但忘了/未正确输入选项 → 原样返回文本（保留开始标记与选项标记），交由用户补全
if (!type) return text;
// 清除所有临时标记（开始标记 + 选项标记），把正文包成 callout
let body = text
  .replace(/\n?【TBPX29待处理文本开始[^\n】]*】\n?/g, '')
  .replace(/\n?【TBPX29本段文字用于让您选择[^】]*您需要的类型是=[^\n】]*】\n?/g, '');
body = body.replace(/^\n+/, '').replace(/\n+$/, '');
// 组装 callout：每行加 "> " 前缀
const lines = body.split('\n').map(l => '> ' + l);
return '> [!' + type + ']\n' + lines.join('\n');
